'use strict';
const M=require('./maps.cjs'),G=require('./generator-v3.cjs'),F=require('./engine/core');
function accepts(rule,e){const p=rule.predicate;return ['y','vy','lead','phase'].every(k=>{const v=e[k]??(k==='y'?270:0);return v>=p[k][0]&&v<=p[k][1];})&&p.adjacency.includes(e.adjacency||'none');}
function compile(components,e={},withBridge=true,{level='stage',name='course',phaseProgression=false}={}){
 const n=components.length;if(![4,12].includes(n)||level==='whole'&&n!==12)throw Error('Unsupported course length');const m=M.base(name,e,n*1200);m.routes={};m.routeMarks=[];m.components=[];
 for(const route of ['main','branch'])m.routes[route]={segments:[],checkpoints:[],events:[],exit:{x:n*1500-220,y:[150,420],vy:[-310,400]},recoveryTicks:120,finalDomain:{y:[245,300],vy:[-65,65]},connectors:[]};
 components.forEach((c,i)=>{const rule=c.rule;if(rule.level!=='combo'||!['wave','mechanical'].includes(rule.theme))throw Error('Unsupported composition dependency');const local={...e,phase:phaseProgression?Math.max(-.4,Math.min(.4,(e.phase||0)+(Math.floor(i/4)-1)*.12)):e.phase||0};if(!accepts(rule,local))throw Error('Outside conditional domain');const off=i*1500,t0=i*10,sub=G.combo(rule.theme,rule.variant,local);
 for(const o of sub.obstacles){const p=structuredClone(o);p.id=`c${i}-${o.id}`;p.group_id=p.id;p.x+=off;if(p.motion?.period_s)p.motion.phase_rad-=t0*2*Math.PI/p.motion.period_s;m.obstacles.push(p);}
 for(const route of ['main','branch']){const assigned=c.swap?(route==='main'?'branch':'main'):route,p=m.routes[route],src=sub.routes[assigned];p.segments.push(...src.segments.map(s=>({...s,endX:Math.min(s.endX,1560)+off})));p.checkpoints.push(...src.checkpoints.map(q=>({...q,id:`c${i}-${q.id}`,x:q.x+off})));if(i<n-1)p.checkpoints.push({id:'handoff-'+i,x:1560+off,y:[245,300],vy:[-65,65]});if(withBridge)p.connectors.push({startX:1120+off,boundaryX:1560+off});}
 m.routeMarks.push({id:'component-'+i,x:1450+off,yMin:10,yMax:530,direction:'forward',portalPolicy:'physical-crossing-only'});m.components.push({ruleId:rule.ruleId,ruleVersion:rule.version,theme:rule.theme,variant:rule.variant,swap:!!c.swap,offset:off,entryPhase:local.phase,phaseAlignment:'authored schedule subtracts component start time; no state or world-clock reset'});
 });m.design={level,theme:'wave-mechanical',primaryGoal:'state-domain connections, alternating rise/fall and timed compression with recovery',withBridge,phaseProgression,components:m.components,routeScope:'main itinerary and one frozen alternate itinerary; mechanical segments use alternate lane not a separate branch',unsupported:['spring stage composition','arbitrary branch itineraries','continuous parameter guarantee','natural readable choices','human fun']};F.validate(m);return m;
}
module.exports={accepts,compile};
